-- create "rte_metered_entitlement_balances" table
CREATE TABLE "rte_metered_entitlement_balances" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "namespace" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "entitlement_id" character(26) NOT NULL,
  "calculated_at" timestamptz NOT NULL,
  "balance" jsonb NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "rte_metered_balance_scope" to table: "rte_metered_entitlement_balances"
CREATE UNIQUE INDEX "rte_metered_balance_scope" ON "rte_metered_entitlement_balances" ("namespace", "entitlement_id") WHERE (deleted_at IS NULL);
-- create index "rtemeteredentitlementbalance_namespace" to table: "rte_metered_entitlement_balances"
CREATE INDEX "rtemeteredentitlementbalance_namespace" ON "rte_metered_entitlement_balances" ("namespace");
